package hagrid.core.routing.sections;
import java.util.*;import hagrid.core.routing.*;import org.matsim.api.core.v01.network.Link;import org.matsim.core.population.routes.RouteUtils;import org.matsim.api.core.v01.*;import org.matsim.core.network.NetworkUtils;import org.matsim.freight.carriers.*;import org.matsim.vehicles.*;
class RemappedAnchorBindingTest {
 static Carrier carrier(String raw,Coord xy,String stop){var c=CarriersUtils.createCarrier(Id.create("c",Carrier.class));var t=VehicleUtils.createVehicleType(Id.create("v",VehicleType.class),"car");t.getCapacity().setOther(10);t.getCostInformation().setCostsPerMeter(0.0);t.getCostInformation().setCostsPerSecond(0.0);t.getCostInformation().setFixedCost(5.0);c.setCarrierCapabilities(CarrierCapabilities.Builder.newInstance().addVehicle(CarrierVehicle.newInstance(Id.createVehicleId("v"),Id.createLinkId("f"),t)).build());var s=CarrierService.Builder.newInstance(Id.create("j",CarrierService.class),Id.createLinkId(raw),1).setServiceDuration(7).setServiceStartingTimeWindow(TimeWindow.newInstance(100,200)).build();s.getAttributes().putAttribute("coord",xy);if(stop!=null)s.getAttributes().putAttribute("stop_id",stop);CarriersUtils.addService(c,s);return c;}
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);} static void fails(Runnable r,String m){try{r.run();throw new AssertionError(m);}catch(IllegalArgumentException expected){}}
 @org.junit.jupiter.api.Test void preservesBinding(){var n=NetworkUtils.createNetwork();var a=NetworkUtils.createAndAddNode(n,Id.createNodeId("a"),new Coord(0,0));var b=NetworkUtils.createAndAddNode(n,Id.createNodeId("b"),new Coord(100,0));var c=NetworkUtils.createAndAddNode(n,Id.createNodeId("c"),new Coord(0,10));var d=NetworkUtils.createAndAddNode(n,Id.createNodeId("d"),new Coord(100,10));NetworkUtils.createAndAddLink(n,Id.createLinkId("f"),a,b,100,10,1000,1);NetworkUtils.createAndAddLink(n,Id.createLinkId("h"),c,d,100,10,1000,1);NetworkUtils.createAndAddLink(n,Id.createLinkId("r"),d,c,100,10,1000,1);
 var h=new PreparedHaltCatalog.Road("c","d",100,100,List.of(new PreparedHaltCatalog.Point(0,10),new PreparedHaltCatalog.Point(100,10)));var r=new PreparedHaltCatalog.Road("d","c",100,100,List.of(new PreparedHaltCatalog.Point(100,10),new PreparedHaltCatalog.Point(0,10)));
 var j=new PreparedHaltCatalog.Job("j","f",List.of(new PreparedHaltCatalog.Approach("r",.75)),"HOME","stop","h",new PreparedHaltCatalog.Point(25,10));var p=new PreparedHaltCatalog("c",Map.of("h",h,"r",r),List.of(j),"f");var roads=SplitRoadNetworkBuilder.build(n,p);var catalog=SectionCatalogBuilder.build(carrier("f",new Coord(25,10),"stop"),roads,50,10);check(catalog.sections().getFirst().variants().size()==1,"reverse only");fails(()->SectionCatalogBuilder.build(carrier("r",new Coord(25,10),"stop"),roads,50,10),"wrong original raw");fails(()->SectionCatalogBuilder.build(carrier("f",new Coord(25,11),"stop"),roads,50,10),"wrong source coordinate");fails(()->SectionCatalogBuilder.build(carrier("f",new Coord(Double.NaN,10),"stop"),roads,50,10),"nonfinite source coordinate");fails(()->SectionCatalogBuilder.build(carrier("f",new Coord(25,10),null),roads,50,10),"missing stop id");fails(()->SectionCatalogBuilder.build(carrier("f",new Coord(25,10),"other"),roads,50,10),"wrong stop id");
 var access=new PreparedHaltCatalog.Job("j","f",List.of(new PreparedHaltCatalog.Approach("r",.75)),"HOME","stop","h",new PreparedHaltCatalog.Point(25,12),new PreparedHaltCatalog.Point(25,10),List.of(new PreparedHaltCatalog.Point(25,12),new PreparedHaltCatalog.Point(25,10)));
 var accessRoads=SplitRoadNetworkBuilder.build(n,new PreparedHaltCatalog("c",Map.of("h",h,"r",r),List.of(access),"f"));
 check(SectionCatalogBuilder.build(carrier("f",new Coord(25,12),"stop"),accessRoads,50,10).sections().size()==1,"source geometry anchor accepted");fails(()->SectionCatalogBuilder.build(carrier("f",new Coord(25,10),"stop"),accessRoads,50,10),"anchor is not customer coordinate");
 fails(()->new PreparedHaltCatalog.Job("j","f",List.of(new PreparedHaltCatalog.Approach("r",.75)),"HOME","stop","h",new PreparedHaltCatalog.Point(25,12),new PreparedHaltCatalog.Point(25,10),List.of(new PreparedHaltCatalog.Point(24,12),new PreparedHaltCatalog.Point(25,10))),"source street geometry mismatch");
 var bad=new PreparedHaltCatalog.Job("j","f",List.of(new PreparedHaltCatalog.Approach("r",.6)),"HOME","stop","h",new PreparedHaltCatalog.Point(25,10));fails(()->SplitRoadNetworkBuilder.build(n,new PreparedHaltCatalog("c",Map.of("h",h,"r",r),List.of(bad),"f")),"anchor point inconsistent");
 SectionRoadCosts costs=new SectionRoadCosts(){public SectionLeg leg(Id<Link>a,Id<Link>b,VehicleType t){return new SectionLeg(10,10,0);}public RoadLeg materialize(Id<Link>a,Id<Link>b,double departure,Vehicle vehicle){var route=RouteUtils.createLinkNetworkRouteImpl(a,b);route.setVehicleId(vehicle.getId());route.setDistance(10);route.setTravelTime(10);return new RoadLeg(route,10,10,0);}public String fingerprint(){return "test";}};
 var result=new CarrierOptimizationService().searchSections(catalog,roads.network(),costs,300,300,0,4711,new SectionSearchPolicy(2,.25,.4));
 var expanded=SectionPlanExpander.expand(result,catalog,costs);
 var selected=roads.jobApproaches().get("j").getFirst().haltLinkId();check(expanded.bindings().get("j").equals(selected),"selected allowed reverse halt");check(catalog.originalCarrier().getServices().get(Id.create("j",CarrierService.class)).getServiceLinkId().toString().equals("f"),"original raw untouched");check(SectionBindingValidator.validatePlan(catalog,expanded.carrier(),expanded.plan(),expanded.bindings()).isEmpty(),"expanded plan validation");var finalJob=expanded.carrier().getServices().get(Id.create("j",CarrierService.class));check(finalJob.getServiceDuration()==7 && finalJob.getServiceStaringTimeWindow().getStart()==100 && finalJob.getServiceStaringTimeWindow().getEnd()==200,"original service duration and window preserved");
 System.out.println("PASS explicit remap source, native jsprit, expansion and plan binding"); }
}
